import "./spacer.css";

export interface SpacerProps {
  size: "xs" | "sm" | "md" | "lg" | "xl";
}

export function Spacer({ size }: SpacerProps) {
  return <div className="p1-spacer" data-size={size} aria-hidden="true" />;
}

import type { ComponentConfig } from "@puckeditor/core";
import { defineMeta } from '../define-meta';
import { Spacer, type SpacerProps } from "./spacer";
export type { SpacerProps };

export const SpacerBlock: ComponentConfig<SpacerProps> = {
  fields: {
    size: {
      type: "select" as const,
      options: [
        { label: "Extra Small", value: "xs" },
        { label: "Small", value: "sm" },
        { label: "Medium", value: "md" },
        { label: "Large", value: "lg" },
        { label: "Extra Large", value: "xl" },
      ],
    },
  },
  defaultProps: {
    size: "md",
  },
  render: Spacer,
};

export const meta = defineMeta({
  title: 'Spacer',
  description: 'Invisible vertical whitespace element in xs–xl sizes; use to add breathing room between blocks.',
  categories: ["content"],
  published: true,
});

.p1-spacer[data-size="xs"] {
  block-size: var(--p1-space-xs);
}

.p1-spacer[data-size="sm"] {
  block-size: var(--p1-space-sm);
}

.p1-spacer[data-size="md"] {
  block-size: var(--p1-space-lg);
}

.p1-spacer[data-size="lg"] {
  block-size: var(--p1-space-xl);
}

.p1-spacer[data-size="xl"] {
  block-size: var(--p1-space-2xl);
}

